INSERT INTO `about_data` (`id`, `headline`, `sub_headline`, `description`, `is_active`, `created_at`, `updated_at`) VALUES (8, 'MỖI THIẾT KẾ LÀ MỘT CÂU CHUYỆN', 'MỖI CÔNG TRÌNH LÀ MỘT DẤU ẤN', 'Thành lập từ năm 2022, PG là đội ngũ kiến trúc sư trẻ đầy đam mê và nhiệt huyết, hoạt động chuyên sâu trong lĩnh vực Kiến trúc - Xây dựng - Nội thất. Chúng tôi mang đến giải pháp toàn diện từ thiết kế ý tưởng đến thi công hoàn thiện, giúp khách hàng tối ưu không gian sống, tiết kiệm thời gian và chi phí, nhưng vẫn đảm bảo thẩm mỹ và công năng.', 1, '2025-07-28 16:31:25', '2025-07-28 16:31:25');
INSERT INTO `about_intro_data` (`id`, `brand_title`, `brand_subtitle`, `identity`, `description_1`, `description_2`, `background_image_url`, `is_active`, `created_at`, `updated_at`) VALUES (4, 'PG DESIGN', 'KIẾN TẠO KHÔNG GIAN', 'KHẲNG ĐỊNH BẢN SẮC', 'Là đơn vị chuyên nghiệp trong lĩnh vực thiết kế kiến trúc, nội thất và thi công trọn gói. Với đội ngũ thiết kế và thi công giàu kinh nghiệm, chúng tôi cam kết mang đến những công trình chất lượng cao, đúng tiến độ và phản ánh rõ rệt tính cách của từng khách hàng.', 'PG Design không chỉ tạo ra những không gian sống và làm việc thẩm mỹ, mà còn góp phần xây dựng bản sắc riêng cho mỗi công trình thông qua thiết kế cá nhân hóa và có chiều sâu, gắn liền với phong cách sống và định hướng thương hiệu của khách hàng. Đây chính là cách chúng tôi mang đến giá trị vượt lên trên vẻ đẹp bề mặt - một không gian có hồn và có ý nghĩa.', 'https://s3-hcm-r2.s3cloud.vn/pgdesign-new/images/thumb-intro.png', 1, '2025-07-28 16:31:19', '2025-10-22 15:31:23');
INSERT INTO `about_project_data` (`id`, `title`, `subtitle`, `is_active`, `created_at`, `updated_at`, `background_image_blob`, `background_image_url`) VALUES (1, 'Dự án', 'PG DESIGN', 1, '2025-10-22 11:45:19', '2025-10-22 14:40:36', NULL, 'https://s3-hcm-r2.s3cloud.vn/pgdesign-new/projectpage/project-hero.png');
