INSERT INTO `commitment_items` (`id`, `commitments_id`, `icon_name`, `title`, `description`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (2, 4, 'quality-materials-icon', 'VẬT TƯ ĐẠT CHUẨN', 'Chúng tôi sử dụng vật liệu chính hãng, đảm bảo độ bền và tính thẩm mỹ cho công trình.', 1, 1, '2025-10-22 15:59:00', '2025-10-22 16:01:35');
INSERT INTO `commitment_items` (`id`, `commitments_id`, `icon_name`, `title`, `description`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (3, 4, 'clear-pricing-icon', 'CHI PHÍ MINH BẠCH', 'Mọi hạng mục đều được minh bạch trong báo giá. Cam kết không phát sinh bất ngờ.', 2, 1, '2025-10-22 15:59:00', '2025-10-22 16:01:35');
INSERT INTO `commitment_items` (`id`, `commitments_id`, `icon_name`, `title`, `description`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (4, 4, 'timely-delivery-icon', 'THI CÔNG ĐÚNG TIẾN ĐỘ', 'Chúng tôi thực hiện công trình đúng tiến độ đã thống nhất với khách hàng.', 3, 1, '2025-10-22 15:59:00', '2025-10-22 16:01:35');
INSERT INTO `commitment_items` (`id`, `commitments_id`, `icon_name`, `title`, `description`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (5, 4, 'reasonable-price-icon', 'GIÁ HỢP LÝ', 'Chi phí thiết kế và thi công được tính toán hợp lý cho khách hàng.', 4, 1, '2025-10-22 15:59:00', '2025-10-22 16:01:35');
