INSERT INTO `core_values` (`id`, `vision_mission_id`, `title`, `description`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (13, 4, '1. Tận tâm & Chuyên nghiệp', 'Đồng hành cùng khách hàng từ bản vẽ đầu tiên dần hoàn thiện công trình, với tinh thần trách nhiệm và thái độ tận tâm.', 0, 1, '2025-10-22 15:56:13', '2025-10-22 16:01:35');
INSERT INTO `core_values` (`id`, `vision_mission_id`, `title`, `description`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (14, 4, '2. Sáng tạo & Cá tính', 'Không gian được thiết kế không chỉ đẹp, mà còn mang dấu ấn riêng, thể hiện rõ "chất" của người sở hữu.', 1, 1, '2025-10-22 15:56:13', '2025-10-22 16:01:35');
INSERT INTO `core_values` (`id`, `vision_mission_id`, `title`, `description`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (15, 4, '3. Chất lượng & Hoàn hảo', 'Luôn chọn giải pháp tốt nhất, vật liệu chất lượng và thi công chỉnh chu để đạt đến sự hoàn hảo trong từng chi tiết.', 2, 1, '2025-10-22 15:56:13', '2025-10-22 16:01:35');
INSERT INTO `core_values` (`id`, `vision_mission_id`, `title`, `description`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (16, 4, '4. Hiệu quả & Kinh tế hợp lý', 'Tối ưu hóa chi phí mà vẫn đảm bảo tính thẩm mỹ, công năng và độ bền của công trình.', 3, 1, '2025-10-22 15:56:13', '2025-10-22 16:01:35');
