INSERT INTO `testimonials` (`id`, `testimonial_header_id`, `name`, `project`, `text`, `avatar_url`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (23, 5, 'CHỊ LAN', 'DỰ ÁN BIỆT THỰ ĐÀ LẠT - Q1', 'Duis autem vel eum iriure dolor in hendrerit in vulputate velit esse molestie consequat, vel illum dolore eu feugiat nulla facilisis at vero eros et accumsan et iusto odio dignissim.', NULL, 2, 1, '2025-07-28 16:31:19', '2025-07-28 16:31:19');
INSERT INTO `testimonials` (`id`, `testimonial_header_id`, `name`, `project`, `text`, `avatar_url`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (24, 5, 'ANH THỊNH', 'NHÀ PHỐ QUẬN 7 - Q1', 'Typi non habent claritatem insitam; est usus legentis in iis qui facit eorum claritatem. Investigationes demonstraverunt lectores legere me lius quod ii legunt saepius.', NULL, 3, 1, '2025-07-28 16:31:19', '2025-07-28 16:31:19');
INSERT INTO `testimonials` (`id`, `testimonial_header_id`, `name`, `project`, `text`, `avatar_url`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES (25, 5, 'CHỊ MAI', 'CĂN HỘ CAO CẤP - Q8', 'Claritas est etiam processus dynamicus, qui sequitur mutationem consuetudium lectorum. Mirum est notare quam littera gothica, quam nunc putamus parum claram, anteposuerit litterarum formas humanitatis per seacula quarta decima et quinta decima.', NULL, 4, 1, '2025-07-28 16:31:19', '2025-07-28 16:31:19');
