INSERT INTO `vision_mission_data` (`id`, `image_url`, `vision_title`, `vision_paragraph_1`, `vision_paragraph_2`, `mission_title`, `core_values_title`, `is_active`, `created_at`, `updated_at`) VALUES (4, 'https://s3-hcm-r2.s3cloud.vn/pgdesign-new/intropage/pg-employee/mission.png', 'TẦM NHÌN', 'PG Design tự hào trở thành đơn vị thiết kế - thi công uy tín hàng đầu: nơi mở không gian không chỉ được đầu tư về công năng và thẩm mỹ, mà còn là nơi kiến tạo câu chuyện bằng không gian sống của người sở hữu.', 'Chúng tôi tin rằng, một không gian đẹp là không gian đặt dấu cảm xúc và đồng điệu với nhu cầu sống, từ đó nâng tầm trải nghiệm và chất lượng cuộc sống mỗi ngày.', 'SỨ MỆNH', 'GIÁ TRỊ CỐT LÕI', 1, '2025-07-28 16:31:19', '2025-10-22 15:56:13');
